def point(title, lines, voice, kind='rule'):
    return (title, lines, voice, kind)

DOCTRINE=[
('Core distinction', point('Two ways income may be transferred', ['Diversion: a superior legal obligation diverts income at its source.','Application: the assessee first earns or receives income, then uses it.'], 'വരുമാനത്തിന്റെ വിനിയോഗത്തിൽ രണ്ട് നിയമസ്ഥിതികളുണ്ട്. Source-ൽ തന്നെ മേലധികാരമുള്ള നിയമബാധ്യത വരുമാനം മാറ്റിയാൽ diversion; ആദ്യം വരുമാനം ലഭിച്ച് പിന്നീട് ഉപയോഗിച്ചാൽ application.'), point('Why timing matters', ['The decisive question is when the obligation operates.','Trace whether income reaches the assessee as their own income first.'], 'പ്രധാന പരിശോധന obligation എപ്പോൾ പ്രവർത്തിക്കുന്നു എന്നതാണ്. വരുമാനം assessee-യുടെ സ്വന്തം വരുമാനമായി ആദ്യം ലഭിക്കുന്നുണ്ടോ എന്ന് കണ്ടെത്തണം.')),
('Overriding title', point('Obligation attached to source', ['A pre-existing enforceable obligation must bind the income-producing source.','The assessee’s title is overridden before the income accrues as their own.'], 'മുൻകൂട്ടിയുള്ള enforceable obligation വരുമാനം സൃഷ്ടിക്കുന്ന source-നോട് ബന്ധിപ്പിച്ചിരിക്കണം. വരുമാനം സ്വന്തം വരുമാനമായി ലഭിക്കുന്നതിന് മുമ്പ് assessee-യുടെ title മറികടക്കണം.'), point('Legal character, not label', ['Calling a payment a “charge” is not enough by itself.','Examine the legal instrument, enforceability, and link to the source.'], 'ഒരു payment-നെ “charge” എന്ന് വിളിച്ചതുകൊണ്ട് മാത്രം diversion ആവില്ല. ബന്ധപ്പെട്ട നിയമരേഖ, ബാധ്യത enforce ചെയ്യാമോ, source-നോടുള്ള ബന്ധം എന്നിവ പരിശോധിക്കണം.')),
('Application of income', point('Income accrues first', ['The assessee obtains the right to receive or control the income.','A later payment discharges an obligation from income already earned.'], 'വരുമാനം ആദ്യം assessee-ക്ക് ലഭിക്കാനുള്ള അവകാശമോ നിയന്ത്രണമോ ഉണ്ടാകുന്നു. പിന്നീട് ആ വരുമാനത്തിൽ നിന്ന് payment നടത്തുന്നത് ഇതിനകം നേടിയ വരുമാനത്തിലെ ബാധ്യത തീർക്കലാണ്.'), point('Use does not erase income', ['A later gift, family payment, or voluntary allocation is ordinarily application.','Tax treatment changes only where a specific statutory deduction or exemption applies.'], 'പിന്നീട് നൽകുന്ന gift, കുടുംബ payment, അല്ലെങ്കിൽ സ്വമേധയാ മാറ്റിവെക്കൽ സാധാരണയായി application ആണ്. പ്രത്യേക statutory deduction അല്ലെങ്കിൽ exemption ഉണ്ടെങ്കിൽ മാത്രമേ tax treatment മാറൂ.')),
('Tax consequence and test', point('Different tax treatment', ['Genuine diversion: the diverted amount is not income accruing to the assessee.','Application: the income remains taxable; later spending is not itself a deduction.'], 'യഥാർത്ഥ diversion ആണെങ്കിൽ മാറ്റിയ തുക assessee-ക്ക് accrue ചെയ്ത വരുമാനമല്ല. Application ആണെങ്കിൽ വരുമാനം taxable ആയി തുടരും; പിന്നീട് ചെലവാക്കിയത് മാത്രം deduction ആവില്ല.'), point('Apply the source test', ['Ask: did the obligation take income away before the assessee acquired it?','If the assessee acquired it first, the payment is application in the ordinary case.'], 'അവസാനമായി ചോദിക്കുക: assessee-ക്ക് വരുമാനം ലഭിക്കുന്നതിന് മുമ്പ് obligation അത് source-ൽ നിന്ന് മാറ്റിയോ? ആദ്യം assessee-ക്കാണ് ലഭിച്ചതെങ്കിൽ സാധാരണയായി അത് application ആണ്.'))]

OLD_SLABS=[
('Regime framework', point('Optional old tax regime', ['The old regime applies when a taxpayer validly opts out of the default regime.','Its deductions and exemptions differ from the default regime.'], 'Default regime-ൽ നിന്ന് സാധുവായി മാറി തിരഞ്ഞെടുക്കുമ്പോഴാണ് old regime ബാധകമാകുന്നത്. ഇതിലെ deductions-ഉം exemptions-ഉം default regime-ൽ നിന്ന് വ്യത്യസ്തമാണ്.'), point('Age categories', ['Old-regime basic exemption depends on age for resident individuals.','The slab structure must be selected for the correct age category.'], 'Resident individual-ന്റെ old-regime basic exemption പ്രായവിഭാഗം അനുസരിച്ച് മാറുന്നു. ശരിയായ age category അനുസരിച്ചുള്ള slab ആണ് തിരഞ്ഞെടുക്കേണ്ടത്.')),
('Basic exemption', point('Under 60 years', ['Basic exemption: ₹2,50,000.','Tax starts on total income above this limit.'], '60 വയസ്സിൽ താഴെയുള്ളവർക്കുള്ള basic exemption ₹2,50,000 ആണ്. ഈ പരിധിക്ക് മുകളിലുള്ള total income-ലാണ് tax തുടങ്ങുന്നത്.'), point('Senior and super senior', ['Age 60 to under 80: basic exemption ₹3,00,000.','Age 80 and above: basic exemption ₹5,00,000.'], '60 മുതൽ 80 വയസ്സിന് താഴെ വരെ exemption ₹3,00,000 ആണ്. 80 വയസ്സും അതിലധികവുമുള്ളവർക്ക് അത് ₹5,00,000 ആണ്.')),
('Progressive slab rates', point('Rates for individuals under 60', ['Up to ₹2.5 lakh: nil; ₹2.5–5 lakh: 5%.','₹5–10 lakh: 20%; above ₹10 lakh: 30%.'], '60 വയസ്സിൽ താഴെയുള്ളവർക്ക് രണ്ടര ലക്ഷം വരെ nil; രണ്ടര മുതൽ അഞ്ച് ലക്ഷം വരെ 5%; അഞ്ച് മുതൽ പത്ത് ലക്ഷം വരെ 20%; പത്ത് ലക്ഷത്തിന് മുകളിൽ 30% നിരക്ക്.'), point('Rates for senior groups', ['Senior citizens: 5% above ₹3 lakh to ₹5 lakh; then 20% to ₹10 lakh.','Super seniors: nil to ₹5 lakh; then 20% to ₹10 lakh; above that 30%.'], 'Senior citizens-ന് മൂന്ന് മുതൽ അഞ്ച് ലക്ഷം വരെയുള്ള ഭാഗത്തിന് 5%, തുടർന്ന് പത്ത് ലക്ഷം വരെ 20% ആണ്. Super senior-ന് അഞ്ച് ലക്ഷം വരെ nil; പത്ത് ലക്ഷം വരെ 20%; അതിന് മുകളിൽ 30% ആണ്.')),
('Reliefs and final levy', point('Section 87A in old regime', ['Resident individual; total income not above ₹5,00,000.','Rebate is the lower of tax payable or ₹12,500.'], 'Old regime-ൽ resident individual-ന്റെ total income അഞ്ച് ലക്ഷം കവിയാത്താൽ Section 87A rebate ലഭിക്കും. Tax payable-ഉം ₹12,500-ഉം തമ്മിലുള്ള കുറഞ്ഞ തുകയാണ് rebate.'), point('Cess and computation order', ['Compute slab tax, apply eligible rebate, then add 4% Health and Education Cess.','Surcharge, where applicable, is governed by the relevant Finance Act.'], 'ആദ്യം slab tax കണക്കാക്കുക; ബാധകമായ rebate കുറച്ചശേഷം 4% Health and Education Cess ചേർക്കുക. Surcharge ബാധകമാണെങ്കിൽ അതത് Finance Act അനുസരിച്ച് കണക്കാക്കണം.'))]

OLD_REBATE=[
('Section 87A scope', point('Who may claim', ['The rebate is for a resident individual.','It is not a deduction from income; it reduces income-tax payable.'], 'Section 87A rebate resident individual-നാണ്. ഇത് വരുമാനത്തിൽ നിന്നുള്ള deduction അല്ല; അടയ്ക്കേണ്ട income tax കുറയ്ക്കുന്ന rebate ആണ്.'), point('Old-regime income condition', ['Total income must not exceed ₹5,00,000.','Check this threshold after computing total income under the Act.'], 'Old regime-ൽ total income ₹5,00,000 കവിയരുത്. നിയമപ്രകാരം total income കണക്കാക്കിയ ശേഷമാണ് ഈ പരിധി പരിശോധിക്കേണ്ടത്.')),
('Rebate amount', point('Maximum rebate', ['Rebate is 100% of income-tax payable, subject to a ₹12,500 cap.','The rebate cannot exceed the tax payable.'], 'Income tax-ന്റെ 100% വരെ rebate ലഭിക്കാം; പരമാവധി പരിധി ₹12,500 ആണ്. Rebate, അടയ്ക്കേണ്ട tax-നെ കവിയില്ല.'), point('Practical formula', ['Rebate = lower of income-tax payable or ₹12,500.','Cess is computed after reducing the rebate.'], 'Rebate കണക്കാക്കാനുള്ള ലളിതമായ രീതി: income tax payable-ഉം ₹12,500-ഉം തമ്മിലുള്ള കുറഞ്ഞ തുക. Rebate കുറച്ച ശേഷമാണ് cess കണക്കാക്കുന്നത്.')),
('Relationship to slab tax', point('Compute tax first', ['Apply the old-regime slab rates to total income.','Do not treat the rebate as a slab or income exemption.'], 'ആദ്യം total income-ൽ old-regime slab rates പ്രയോഗിച്ച് tax കണക്കാക്കുക. Rebate-നെ slab ആയോ income exemption ആയോ കാണരുത്.'), point('Apply rebate next', ['Deduct the eligible rebate from income-tax payable.','If rebate equals the tax, balance income-tax becomes nil.'], 'ശേഷം അർഹമായ rebate income tax-ൽ നിന്ന് കുറയ്ക്കുക. Rebate tax-നോട് തുല്യമാണെങ്കിൽ ശേഷിക്കുന്ന income tax nil ആകും.')),
('Limits and sequence', point('Eligibility boundary', ['The ₹5 lakh test is a total-income threshold.','If total income exceeds it, the old-regime rebate is unavailable.'], 'അഞ്ച് ലക്ഷം രൂപയുടെ പരിശോധന total income-നെ അടിസ്ഥാനമാക്കിയാണ്. Total income അതിൽ കൂടുതലായാൽ old-regime rebate ലഭ്യമല്ല.'), point('Final tax sequence', ['Slab tax → Section 87A rebate → surcharge, if applicable → 4% cess.','Follow the assessment-year rules and rounding requirements.'], 'Tax കണക്കാക്കുന്ന ക്രമം: slab tax, Section 87A rebate, ബാധകമായ surcharge, തുടർന്ന് 4% cess. ബന്ധപ്പെട്ട assessment year-ലെ നിയമവും rounding-ഉം പാലിക്കണം.'))]

NEW_SLABS=[
('Section 115BAC framework', point('Default regime', ['Section 115BAC(1A) provides the default regime for specified persons.','Eligible taxpayers may opt for the old regime subject to the applicable option rules.'], 'Section 115BAC(1A) നിർദ്ദിഷ്ട വിഭാഗങ്ങൾക്ക് default regime നൽകുന്നു. ബാധകമായ option വ്യവസ്ഥകൾ പാലിച്ച് അർഹരായവർക്ക് old regime തിരഞ്ഞെടുക്കാം.'), point('Specified taxpayer classes', ['Individuals, HUFs, AOPs (other than co-operative societies), BOIs and AJPs.','The section’s conditions and disallowances apply when this regime is chosen.'], 'Individuals, HUF, co-operative society അല്ലാത്ത AOP, BOI, AJP എന്നിവർക്കാണ് വ്യവസ്ഥ ബാധകമാകുന്നത്. ഈ regime തിരഞ്ഞെടുക്കുമ്പോൾ അതിലെ നിബന്ധനകളും deduction നിയന്ത്രണങ്ങളും ബാധകമാണ്.')),
('Slabs: first part', point('Nil and 5% slabs', ['Up to ₹4,00,000: nil.','₹4,00,001–₹8,00,000: 5%.'], 'നാല് ലക്ഷം രൂപ വരെ tax ഇല്ല. നാല് ലക്ഷം മുതൽ എട്ട് ലക്ഷം വരെയുള്ള slab-ിന് 5% ആണ്.'), point('10% slab', ['₹8,00,001–₹12,00,000: 10%.','Tax is progressive: each rate applies only to its slab portion.'], 'എട്ട് ലക്ഷം മുതൽ പന്ത്രണ്ട് ലക്ഷം വരെയുള്ള slab-ിന് 10% ആണ്. ഓരോ നിരക്കും അതത് slab-ിലെ വരുമാനഭാഗത്തിന് മാത്രം പ്രയോഗിക്കുന്ന progressive രീതിയാണ്.')),
('Slabs: upper part', point('15% and 20% slabs', ['₹12–16 lakh: 15%; ₹16–20 lakh: 20%.','Each slab has a fixed tax accumulated from the earlier slabs.'], 'പന്ത്രണ്ട് മുതൽ പതിനാറ് ലക്ഷം വരെ 15%; പതിനാറ് മുതൽ ഇരുപത് ലക്ഷം വരെ 20%. മുൻ slab-ുകളിലെ tax കൂട്ടിച്ചേർത്താണ് തുടർന്നുള്ള tax കണ്ടെത്തുന്നത്.'), point('25% and 30% slabs', ['₹20–24 lakh: 25%.','Above ₹24 lakh: 30%.'], 'ഇരുപത് മുതൽ ഇരുപത്തിനാല് ലക്ഷം വരെ 25% ആണ്. ഇരുപത്തിനാല് ലക്ഷം രൂപയ്ക്ക് മുകളിലുള്ള ഭാഗത്തിന് 30% ആണ്.')),
('Reliefs and regime features', point('No age-based exemption increase', ['The basic exemption under this regime does not rise for senior age groups.','Use the same slab thresholds regardless of age.'], 'ഈ regime-ൽ മുതിർന്ന പ്രായവിഭാഗങ്ങൾക്ക് basic exemption ഉയരുന്നില്ല. പ്രായം നോക്കാതെ ഒരേ slab പരിധികളാണ് ഉപയോഗിക്കുന്നത്.'), point('Rebate and cess', ['Eligible resident individuals: Section 87A rebate up to ₹60,000 when total income is within ₹12 lakh.','Apply 4% cess after eligible rebate; marginal rebate may apply just above the threshold.'], 'Total income ₹12 ലക്ഷം കവിയാത്ത അർഹനായ resident individual-ന് Section 87A പ്രകാരം പരമാവധി ₹60,000 rebate ലഭിക്കും. Rebate-ന് ശേഷം 4% cess ചേർക്കുക; പരിധിക്ക് തൊട്ടുമുകളിലെ വരുമാനത്തിൽ marginal rebate ബാധകമായേക്കാം.'))]

NEW_REBATE=[
('Eligibility', point('Eligible person', ['Section 87A rebate is available to a resident individual.','The default regime’s limit is distinct from the old-regime limit.'], 'Section 87A rebate resident individual-നാണ്. Default regime-ിലെ പരിധി old regime-ിലെ പരിധിയിൽ നിന്ന് വ്യത്യസ്തമാണ്.'), point('Income threshold', ['For A.Y. 2026–27, total income must not exceed ₹12,00,000 for the standard rebate.','Check total income after applying the Act’s computation rules.'], '2026–27 assessment year-ൽ സാധാരണ rebate ലഭിക്കാൻ total income ₹12,00,000 കവിയരുത്. നിയമപ്രകാരമുള്ള income computation കഴിഞ്ഞാണ് പരിധി പരിശോധിക്കുന്നത്.')),
('Rebate amount', point('Maximum and cap', ['Rebate is up to 100% of income-tax payable.','Maximum rebate under the default regime: ₹60,000.'], 'അടയ്ക്കേണ്ട income tax-ന്റെ 100% വരെ rebate ലഭിക്കും. Default regime-ൽ rebate-ന്റെ പരമാവധി ₹60,000 ആണ്.'), point('Rebate is tax relief', ['It reduces tax, not total income.','It cannot exceed the eligible income-tax payable.'], 'ഇത് total income കുറയ്ക്കുന്നതല്ല, tax കുറയ്ക്കുന്നതാണ്. അർഹമായ income tax-നെക്കാൾ rebate കൂടുതലാകില്ല.')),
('Calculation order', point('Compute slab tax', ['Apply Section 115BAC slab rates progressively.','Determine income-tax before rebate.'], 'Section 115BAC slab നിരക്കുകൾ progressive ആയി പ്രയോഗിച്ച് ആദ്യം rebate-നു മുമ്പുള്ള income tax കണക്കാക്കുക.'), point('Deduct the rebate', ['Where eligible, reduce tax by the lower of tax payable or ₹60,000.','Then compute cess on the remaining tax.'], 'അർഹതയുണ്ടെങ്കിൽ tax payable-ഉം ₹60,000-ഉം തമ്മിലുള്ള കുറഞ്ഞ തുക കുറയ്ക്കുക. ശേഷിക്കുന്ന tax-ലാണ് cess കണക്കാക്കുന്നത്.')),
('Boundary and conditions', point('Income above ₹12 lakh', ['The standard full-threshold rebate is not available above ₹12 lakh.','Marginal rebate may limit the tax increase immediately above the threshold.'], 'Income ₹12 ലക്ഷം കവിയുമ്പോൾ സാധാരണ threshold rebate ലഭ്യമല്ല. പരിധിക്ക് തൊട്ടുമുകളിലെ tax വർധന marginal rebate വഴി നിയന്ത്രിക്കാം.'), point('Cess and special income', ['Health and Education Cess is 4% after rebate.','Special-rate income may have separate rebate restrictions; check the applicable law.'], 'Rebate കഴിഞ്ഞ് Health and Education Cess 4% കണക്കാക്കുക. Special-rate income-ന് rebate സംബന്ധിച്ച പ്രത്യേക നിയന്ത്രണങ്ങളുണ്ടാകാം; ബാധകമായ നിയമം പരിശോധിക്കണം.'))]

MARGINAL_REBATE=[
('Threshold and purpose', point('Threshold rule', ['Standard Section 87A rebate is available up to total income of ₹12 lakh.','A limited marginal rebate can apply when total income is slightly above ₹12 lakh.'], 'Section 87A-യുടെ സാധാരണ rebate total income ₹12 ലക്ഷം വരെ ലഭ്യമാണ്. അതിന് തൊട്ടുമുകളിലെ income-ൽ പരിമിതമായ marginal rebate ലഭിക്കാം.'), point('Purpose of marginal rebate', ['It prevents the tax increase from exceeding the income increase over ₹12 lakh.','The comparison is made before cess.'], '₹12 ലക്ഷം threshold കടന്നതുകൊണ്ട് tax വർധന, അധിക വരുമാനത്തെക്കാൾ കൂടുതലാകാതിരിക്കാൻ marginal rebate സഹായിക്കുന്നു. ഈ താരതമ്യം cess-നു മുമ്പാണ്.')),
('Compute tax first', point('Progressive slab calculation', ['Apply the Section 115BAC slabs to total income.','Find income-tax before Section 87A rebate and cess.'], 'Total income-ൽ Section 115BAC slabs പ്രയോഗിക്കുക. Section 87A rebate-നും cess-നും മുമ്പുള്ള income tax കണ്ടെത്തുക.'), point('Find excess income', ['Excess = total income − ₹12,00,000.','This excess sets the marginal tax ceiling before cess.'], 'അധിക വരുമാനം = total income − ₹12,00,000. Cess-നു മുമ്പുള്ള tax-ന്റെ പരിധി ഈ അധിക തുകയാണ്.')),
('Marginal rebate formula', point('Compare tax with excess', ['If tax before rebate exceeds the excess income, marginal relief is relevant.','Marginal rebate = tax before rebate − excess income, limited by statutory rebate rules.'], 'Rebate-നു മുമ്പുള്ള tax, അധിക വരുമാനത്തെക്കാൾ കൂടുതലാണെങ്കിൽ marginal relief പ്രസക്തമാണ്. നിയമത്തിലെ പരിധിക്ക് വിധേയമായി marginal rebate = tax before rebate − അധിക വരുമാനം.'), point('Cap tax before cess', ['Tax after rebate is restricted so it does not exceed income above ₹12 lakh.','Do not include cess in this comparison.'], 'Rebate ശേഷമുള്ള tax, ₹12 ലക്ഷത്തിന് മുകളിലുള്ള വരുമാനത്തെ കവിയരുത്. ഈ താരതമ്യത്തിൽ cess ഉൾപ്പെടുത്തരുത്.')),
('Finish computation', point('Apply cess afterward', ['After rebate, add Health and Education Cess at 4%.','Cess is calculated on the tax remaining after relief.'], 'Rebate കുറച്ചശേഷം 4% Health and Education Cess ചേർക്കുക. Relief ശേഷമുള്ള tax-ലാണ് cess കണക്കാക്കേണ്ടത്.'), point('Use the right eligibility rules', ['Confirm residency, total-income threshold and nature of income.','Special-rate income can carry separate rebate restrictions.'], 'Residency, total-income threshold, വരുമാനത്തിന്റെ സ്വഭാവം എന്നിവ ഉറപ്പാക്കണം. Special-rate income-ന് rebate സംബന്ധിച്ച വേറിട്ട നിയന്ത്രണങ്ങൾ ഉണ്ടാകാം.'))]

COMPANY_RELIEF=[
('Company tax framework', point('Normal domestic-company rate', ['Domestic companies use the rate prescribed by the relevant Finance Act.','The regular rate is generally 30%; specified turnover-based eligibility can provide 25%.'], 'Domestic company-കൾക്ക് അതത് Finance Act നിശ്ചയിക്കുന്ന നിരക്കാണ് ബാധകം. സാധാരണ നിരക്ക് 30%; നിശ്ചിത turnover വ്യവസ്ഥ പാലിച്ചാൽ 25% നിരക്ക് ലഭിക്കാം.'), point('Concessional regimes', ['Sections 115BA, 115BAA and 115BAB provide separate tax options.','Eligibility, conditions, surcharge and deduction restrictions differ by option.'], 'Sections 115BA, 115BAA, 115BAB എന്നിവ വേറിട്ട tax options നൽകുന്നു. Option അനുസരിച്ച് അർഹത, നിബന്ധന, surcharge, deduction നിയന്ത്രണം എന്നിവ മാറും.')),
('Surcharge', point('Surcharge thresholds', ['For a regular domestic company: 7% where income exceeds ₹1 crore up to ₹10 crore.','12% applies where income exceeds ₹10 crore; surcharge is on income-tax.'], 'സാധാരണ domestic company-ക്ക് income ഒരു കോടി കവിയുകയും പത്ത് കോടി വരെ ആയിരിക്കുകയും ചെയ്താൽ 7% surcharge. പത്ത് കോടി കവിയുമ്പോൾ 12%; surcharge income tax-ലാണ് കണക്കാക്കുന്നത്.'), point('Cess', ['Health and Education Cess is 4% of income-tax plus surcharge.','Add cess after determining any applicable marginal relief.'], 'Income tax-ും surcharge-ും ചേർന്ന തുകയ്ക്ക് 4% Health and Education Cess ബാധകമാണ്. Marginal relief ഉണ്ടെങ്കിൽ അത് കണക്കാക്കിയ ശേഷമാണ് cess ചേർക്കുന്നത്.')),
('Marginal relief above ₹1 crore', point('When it applies', ['Relief addresses the surcharge increase at the ₹1 crore threshold.','Compare tax plus surcharge with threshold tax plus income exceeding ₹1 crore.'], 'ഒരു കോടി രൂപയുടെ threshold കടക്കുമ്പോൾ surcharge മൂലം വരുന്ന അധികഭാരം കുറയ്ക്കാനാണ് marginal relief. Tax plus surcharge-നെ threshold tax-ും ഒരു കോടിക്ക് മുകളിലെ അധിക വരുമാനവും ചേർന്ന തുകയുമായി താരതമ്യം ചെയ്യുക.'), point('Formula', ['Ceiling = tax and surcharge on ₹1 crore + (total income − ₹1 crore).','Relief = tax and surcharge before relief − ceiling, where positive.'], 'പരമാവധി പരിധി = ഒരു കോടി രൂപയിലെ tax-ും surcharge-ും + (total income − ഒരു കോടി). Relief = relief-നു മുമ്പുള്ള tax plus surcharge − ഈ പരിധി; വ്യത്യാസം positive ആണെങ്കിൽ.')),
('Marginal relief above ₹10 crore', point('Higher surcharge threshold', ['At income above ₹10 crore, the regular-company surcharge rate is 12%.','Marginal relief limits the threshold jump at ₹10 crore.'], 'പത്ത് കോടി കവിയുന്ന income-ൽ സാധാരണ company surcharge 12% ആണ്. പത്ത് കോടിയുടെ threshold-ൽ ഉണ്ടാകുന്ന tax jump marginal relief നിയന്ത്രിക്കുന്നു.'), point('Formula and order', ['Ceiling = tax plus surcharge on ₹10 crore + income exceeding ₹10 crore.','Deduct relief, then add 4% cess to tax plus surcharge.'], 'പരമാവധി പരിധി = പത്ത് കോടി രൂപയിലെ tax plus surcharge + അതിന് മുകളിലെ വരുമാനം. Relief കുറച്ചശേഷം ശേഷിക്കുന്ന tax plus surcharge-ൽ 4% cess ചേർക്കുക.'))]

