INTRO={
1:'ഇന്ന് Section 4-ലെ diversion of income, application of income എന്നീ നിയമസങ്കൽപ്പങ്ങൾ മാത്രം പഠിക്കാം.',
2:'ഇന്ന് overriding title വഴി income diversion ആകുന്നതിന്റെ നിയമതത്വം മാത്രം നോക്കാം.',
3:'ഇന്ന് source-ൽ diversion-ഉം income ലഭിച്ച ശേഷമുള്ള application-ഉം തമ്മിലുള്ള നിയമവ്യത്യാസം മാത്രം പഠിക്കാം.',
4:'ഇന്ന് old tax regime-ലെ age-based slab വ്യവസ്ഥകൾ മാത്രം നോക്കാം.',
5:'ഇന്ന് Section 87A-യുടെ old-regime rebate വ്യവസ്ഥ മാത്രം പഠിക്കാം.',
6:'ഇന്ന് Section 115BAC default regime-ലെ tax slab നിയമങ്ങൾ മാത്രം പഠിക്കാം.',
7:'ഇന്ന് default regime-ലെ Section 87A rebate വ്യവസ്ഥ മാത്രം നോക്കാം.',
8:'ഇന്ന് Section 87A പ്രകാരമുള്ള marginal rebate വ്യവസ്ഥ മാത്രം പഠിക്കാം.',
9:'ഇന്ന് domestic company-കൾക്ക് ഒരു കോടി രൂപ threshold-ൽ ബാധകമായ surcharge relief മാത്രം നോക്കാം.',
10:'ഇന്ന് domestic company-കൾക്ക് പത്ത് കോടി രൂപ threshold-ൽ ബാധകമായ surcharge relief മാത്രം പഠിക്കാം.'}

def main():
    provisions=json.loads((ROOT/'data'/'provisions.json').read_text(encoding='utf-8'))
    for p in provisions:
        q=int(p['question_number']); title,sections,groups=SETS[q]
        p['topic_title']=title; p['core_principle']=title; p['statutory_sections']=sections
        p['provision_presentation_markdown']='## '+title+'\n\n'+'\n'.join('### '+name+'\n'+'\n'.join('- '+line for pt in pts for line in pt[1]) for name, *pts in groups)
        out=[{'id':'INTRO','number':'1','block':0,'block_name':'Provision heading','narration_ml':INTRO[q],'card':{'title':title,'type':'intro','lines':[],'highlights':[]}}]
        for block,(branch, *pts) in enumerate(groups,1):
            for sub,(name,lines,voice,kind) in enumerate(pts,1):
                out.append({'id':f'L{(block-1)*2+sub:02d}','number':f'1.{block}.{sub}','block':block,'block_name':branch,'narration_ml':voice,'card':{'title':name,'type':kind,'lines':lines,'highlights':[]}})
        (SCRIPTS/f'q{q}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'data'/'provisions.json').write_text(json.dumps(provisions,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Wrote provision-only summaries and narration scripts for Q1–Q10.')

if __name__=='__main__': main()
